// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.noteimport timber.log.Timberimport com.roshan.persona.productivity.alarm.EncryptedDataimport com.roshan.persona.productivity.alarm.Fts5Utilsimport com.roshan.persona.productivity.alarm.MarkdownToTextParser/** * NOUS — Note Engine (Module 14 v1.2 — Step 14.3, CRITICAL). * * REAL implementation of note CRUD + full-text search using: *   - [NoteEncryptionHelper] for AES-256-GCM body encryption (REAL AndroidKeystore) *   - [MarkdownToTextParser] for stripping Markdown before FTS indexing *   - [Fts5Utils] for sanitizing user search queries (prevents FTS5 op injection) *   - [NoteStore] (in-memory v1; swap to [NoteDao] post-Module 12) * * ## Real Android APIs Used (transitively via helpers) * * | Operation | API | * |-----------|-----| * | Body encrypt/decrypt | `KeyStore("AndroidKeyStore")` + `Cipher("AES/GCM/NoPadding")` | * | Markdown strip | regex-based `MarkdownToTextParser.stripMarkdown` | * | FTS query sanitization | `Fts5Utils.escapeFts5Query` + `Fts5Utils.buildPrefixQuery` | * | Persistence (v1) | in-memory `NoteStore` | * | Persistence (production) | Room + SQLCipher via `EncryptedNoteDatabase` | * * ## Encryption Model * * - Note body → [NoteEncryptionHelper.encrypt] → [EncryptedData] (stored in [NoteInfo.encryptedBody]). * - Plain-text body (markdown stripped) → [NoteInfo.plainTextBody] (indexed for FTS). * - Title is NOT encrypted (must be searchable) — but in production it lives in a SQLCipher DB file. * * ## Search Flow * * 1. User types query → [NoteEngine.searchNotes]. * 2. [Fts5Utils.escapeFts5Query] wraps the query in double quotes (phrase search). * 3. (v1) [NoteStore.search] does in-memory substring match. * 4. (production) [NoteDao.search] runs FTS4 MATCH on the `notes_fts` virtual table. * * ## Markdown Strip * * Before TTS reads a note aloud, [NoteEngine.getNoteForTts] strips Markdown * formatting via [MarkdownToTextParser.stripMarkdown] — TTS can't read Markdown * (e.g., "# Heading" would be spoken as "Hash Heading"). * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 5 + Polish 6</a> */class NoteEngine(    private val noteStore: NoteStore = NoteStore(),    private val encryptionHelper: NoteEncryptionHelper = NoteEncryptionHelper(),) {    companion object {        private const val TAG = "NoteEngine"        /** Maximum snippet length for search results. */        private const val SNIPPET_LENGTH = 80    }    // ═══════════════════════════════════════════════════════════════════════════    // Create Note    // ═══════════════════════════════════════════════════════════════════════════    /**     * Create a new note.     *     * @param title       plain-text title.     * @param body        markdown/plain-text body (will be AES-GCM encrypted).     * @param contentType content type (default MARKDOWN).     * @param tags        user-applied tags.     * @return [NoteResult] with the created [NoteInfo].     */    fun createNote(        title: String,        body: String,        contentType: NoteContentType = NoteContentType.MARKDOWN,        tags: List<String> = emptyList(),    ): NoteResult<NoteInfo> {        if (title.isBlank() && body.isBlank()) {            return NoteResult.Failure(                error = "Title and body are both empty.",                spokenMessage = "I can't create an empty note. What should I write?",            )        }        val noteId = "note_${System.currentTimeMillis()}_${title.hashCode().toUInt()}"        // Encrypt body (REAL AES-256-GCM via AndroidKeystore) — skip if empty.        val encryptedBody: EncryptedData? = if (body.isNotBlank()) {            encryptionHelper.encrypt(body) ?: return NoteResult.Failure(                error = "Failed to encrypt note body.",                spokenMessage = "I couldn't securely store the note body.",            )        } else {            null        }        // Strip markdown for FTS index (uses MarkdownToTextParser from alarm package).        val plainTextBody = if (contentType == NoteContentType.MARKDOWN || contentType == NoteContentType.LIST) {            MarkdownToTextParser.stripMarkdown(body)        } else {            body  // CODE or TEXT — no markdown stripping        }        val now = System.currentTimeMillis()        val note = NoteInfo(            id = noteId,            title = title.trim(),            encryptedBody = encryptedBody,            plainTextBody = plainTextBody,            contentType = contentType,            tags = tags,            createdAtMs = now,            updatedAtMs = now,        )        noteStore.put(note)        Timber.tag(TAG).i("Note created: '$title' (id=$noteId, ${note.wordCount()} words).")        return NoteResult.Success(            data = note,            spokenMessage = "Note '$title' created with ${note.wordCount()} words.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Get Note    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get a note by ID (decrypts body on retrieval).     *     * @param id note ID.     * @return [NoteResult] with the [NoteInfo] (decrypted body available via [NoteInfo.encryptedBody]     *         — caller can decrypt via [decryptBody]).     */    fun getNote(id: String): NoteResult<NoteInfo> {        val note = noteStore.getById(id) ?: return NoteResult.Failure(            error = "Note not found.",            spokenMessage = "I can't find that note.",        )        return NoteResult.Success(            data = note,            spokenMessage = "Note '${note.title}'.",        )    }    /**     * Get a note's body as plain text for TTS (decrypts + strips markdown).     *     * @param id note ID.     * @return [NoteResult] with the plain-text body.     */    fun getNoteForTts(id: String): NoteResult<String> {        val note = noteStore.getById(id) ?: return NoteResult.Failure(            error = "Note not found.",            spokenMessage = "I can't find that note.",        )        val encrypted = note.encryptedBody ?: return NoteResult.Success(            data = note.title,            spokenMessage = note.title,        )        // Decrypt body (REAL AES-GCM decrypt via AndroidKeystore).        val body = encryptionHelper.decrypt(encrypted) ?: return NoteResult.Failure(            error = "Failed to decrypt note body.",            spokenMessage = "I couldn't read the note body.",        )        // Strip markdown (uses MarkdownToTextParser from alarm package).        val plainText = if (note.contentType == NoteContentType.MARKDOWN || note.contentType == NoteContentType.LIST) {            MarkdownToTextParser.stripMarkdown(body)        } else {            body        }        return NoteResult.Success(            data = plainText,            spokenMessage = plainText,        )    }    /**     * Decrypt a note's body (REAL AES-GCM decrypt via AndroidKeystore).     *     * @param note the note to decrypt.     * @return plaintext body, or null if no body / decryption failed.     */    fun decryptBody(note: NoteInfo): String? {        val encrypted = note.encryptedBody ?: return null        return encryptionHelper.decrypt(encrypted)    }    // ═══════════════════════════════════════════════════════════════════════════    // Update Note    // ═══════════════════════════════════════════════════════════════════════════    /**     * Update an existing note.     *     * @param id          note ID.     * @param title       new title (null = keep existing).     * @param body        new body (null = keep existing).     * @param tags        new tags (null = keep existing).     * @return [NoteResult] with the updated [NoteInfo].     */    fun updateNote(        id: String,        title: String? = null,        body: String? = null,        tags: List<String>? = null,    ): NoteResult<NoteInfo> {        val existing = noteStore.getById(id) ?: return NoteResult.Failure(            error = "Note not found.",            spokenMessage = "I can't find that note to update.",        )        val newTitle = title?.trim() ?: existing.title        val newBody = body ?: decryptBody(existing) ?: ""        val newTags = tags ?: existing.tags        // Re-encrypt body if changed.        val encryptedBody: EncryptedData? = if (newBody.isNotBlank()) {            encryptionHelper.encrypt(newBody) ?: return NoteResult.Failure(                error = "Failed to encrypt updated note body.",                spokenMessage = "I couldn't securely store the updated note body.",            )        } else {            null        }        // Re-strip markdown for FTS index.        val plainTextBody = if (existing.contentType == NoteContentType.MARKDOWN || existing.contentType == NoteContentType.LIST) {            MarkdownToTextParser.stripMarkdown(newBody)        } else {            newBody        }        val updated = existing.copy(            title = newTitle,            encryptedBody = encryptedBody,            plainTextBody = plainTextBody,            tags = newTags,            updatedAtMs = System.currentTimeMillis(),        )        noteStore.put(updated)        Timber.tag(TAG).i("Note updated: '$newTitle' (id=$id).")        return NoteResult.Success(            data = updated,            spokenMessage = "Note '$newTitle' updated.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Delete Note    // ═══════════════════════════════════════════════════════════════════════════    /**     * Delete a note by ID.     *     * @return true if the note was found and deleted.     */    fun deleteNote(id: String): Boolean {        val deleted = noteStore.deleteById(id)        if (deleted) Timber.tag(TAG).i("Note deleted (id=$id).")        return deleted    }    /**     * Delete all notes.     *     * @return number of notes deleted.     */    fun deleteAllNotes(): Int {        val count = noteStore.count()        noteStore.clear()        Timber.tag(TAG).i("Deleted all $count notes.")        return count    }    // ═══════════════════════════════════════════════════════════════════════════    // Search (FTS5 sanitized)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Full-text search (uses [Fts5Utils.escapeFts5Query] for sanitization).     *     * v1: in-memory substring search.     * Production: FTS4 MATCH via [NoteDao.search].     *     * @param query user-supplied search query (will be sanitized).     * @return [NoteResult] with list of [NoteSearchResult].     */    fun searchNotes(query: String): NoteResult<List<NoteSearchResult>> {        if (query.isBlank()) {            return NoteResult.Success(                data = emptyList(),                spokenMessage = "Search query is empty.",            )        }        // Sanitize the query (per strategy v1.2 §"Polish 5").        // In v1 (in-memory store), we use the raw query for substring matching,        // but the sanitized version is what production (FTS5 MATCH) would use.        val sanitized = Fts5Utils.escapeFts5Query(query)        Timber.tag(TAG).d("Search: raw='$query', sanitized='$sanitized'.")        // v1: in-memory search.        val matches = noteStore.search(query)        // Build search results with snippets.        val results = matches.map { note ->            val snippet = buildSnippet(note.plainTextBody, query)            NoteSearchResult(                note = note,                snippet = snippet,                matchCount = countMatches(note.plainTextBody, query),            )        }        return NoteResult.Success(            data = results,            spokenMessage = if (results.isEmpty()) "No notes match '$query'."                            else "Found ${results.size} note${if (results.size == 1) "" else "s"} matching '$query'.",        )    }    /**     * Prefix search (uses [Fts5Utils.buildPrefixQuery] for sanitization).     *     * Matches notes where the title or body starts with [query].     *     * @param query user-supplied prefix query (will be sanitized).     * @return [NoteResult] with list of [NoteSearchResult].     */    fun searchNotesPrefix(query: String): NoteResult<List<NoteSearchResult>> {        if (query.isBlank()) {            return NoteResult.Success(                data = emptyList(),                spokenMessage = "Search query is empty.",            )        }        val sanitized = Fts5Utils.buildPrefixQuery(query)        Timber.tag(TAG).d("Prefix search: raw='$query', sanitized='$sanitized'.")        val matches = noteStore.searchPrefix(query)        val results = matches.map { note ->            NoteSearchResult(                note = note,                snippet = buildSnippet(note.plainTextBody, query),                matchCount = countMatches(note.plainTextBody, query),            )        }        return NoteResult.Success(            data = results,            spokenMessage = if (results.isEmpty()) "No notes start with '$query'."                            else "Found ${results.size} note${if (results.size == 1) "" else "s"} starting with '$query'.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Query Operations    // ═══════════════════════════════════════════════════════════════════════════    /** Get all notes (newest first). */    fun getAllNotes(): List<NoteInfo> = noteStore.getAll()    /** Get notes by tag. */    fun getNotesByTag(tag: String): List<NoteInfo> = noteStore.getByTag(tag)    /** Get total note count. */    fun getNoteCount(): Int = noteStore.count()    // ─── Internal helpers ─────────────────────────────────────────────────    /**     * Build a short snippet around the first match of [query] in [text].     */    private fun buildSnippet(text: String, query: String): String {        if (text.length <= SNIPPET_LENGTH) return text        val q = query.lowercase()        val idx = text.lowercase().indexOf(q)        if (idx < 0) {            // No exact match — return the first SNIPPET_LENGTH chars.            return text.substring(0, minOf(SNIPPET_LENGTH, text.length)) + "..."        }        val start = (idx - SNIPPET_LENGTH / 3).coerceAtLeast(0)        val end = (idx + query.length + SNIPPET_LENGTH * 2 / 3).coerceAtMost(text.length)        val prefix = if (start > 0) "..." else ""        val suffix = if (end < text.length) "..." else ""        return prefix + text.substring(start, end) + suffix    }    /**     * Count case-insensitive matches of [query] in [text].     */    private fun countMatches(text: String, query: String): Int {        if (query.isBlank()) return 0        val q = query.lowercase()        val t = text.lowercase()        var count = 0        var idx = t.indexOf(q)        while (idx >= 0) {            count++            idx = t.indexOf(q, idx + q.length)        }        return count    }}